def min_covering_window(values, required):
    if not required:
        return [0, 0]

    need = {}
    for x in required:
        need[x] = need.get(x, 0) + 1

    have = {}
    formed = 0
    required_types = len(need)

    l = 0
    best = None

    for r, val in enumerate(values):
        have[val] = have.get(val, 0) + 1
        if val in need and have[val] == need[val]:
            formed += 1

        while formed == required_types and l <= r:
            start, end = l, r + 1
            length = end - start
            if best is None or length < best[0] or (length == best[0] and start < best[1]):
                best = (length, start, end)

            left_val = values[l]
            have[left_val] -= 1
            if left_val in need and have[left_val] < need[left_val]:
                formed -= 1
            l += 1

    if best is None:
        return None
    return [best[1], best[2]]

